trait Term { type V <: Visitor; def accept(v: V): Unit }          // element, open over visitor type
trait Visitor { def visitUnknown(t: Term): Unit }                 // the default case

trait Nat extends Term { type V <: NatVisitor }                   // element extension
trait NatVisitor extends Visitor { def visitZero(z: Zero): Unit } // visitor extension

class Eval extends Visitor { def visitUnknown(t: Term): Unit = () }
class EvalNat extends Eval with NatVisitor {                      // operation extension by mixin
  override def visitUnknown(t: Term): Unit = t.accept(this)        // re-dispatch new variants
  def visitZero(z: Zero): Unit = ()
}
